from .coco_section_generic import YAMLBasedSectionGeneric


class SectionUes(YAMLBasedSectionGeneric):
    def __init__(self, section_name='UEs'):
        super().__init__(section_name)

    def _prepare_section_content(self, ue_config, *args, **kwargs):
        bearers = {}
        bearer_set = {}
        bearer_sets = []
        ues = ue_config['ue']
        qci_basic_param_def = ue_config['qci']
        selected_bearer_set = ues['1-1000']['bearer'] if '1-1000' in ues else 'default'
        bearer_set[selected_bearer_set] = ue_config['bearer'][selected_bearer_set] if selected_bearer_set in ue_config['bearer'] else []

        for qci_definition in bearer_set[selected_bearer_set]:
            for basic_qci_param_k, basic_qci_param_v in qci_basic_param_def.items():
                if int(basic_qci_param_k) == int(qci_definition['qci']):
                    qci_definition.update(basic_qci_param_v)

            keys_to_parse = ('qci', 'gbr_dl', 'gbr_ul', 'mbr_ul', 'mbr_dl', 'pdn', 'priority', 'delay')
            parsed_qci_definition = {k: (int(v) if k in keys_to_parse else v) for k, v in qci_definition.items()}
            bearer_sets.append(parsed_qci_definition)
        bearers[selected_bearer_set] = bearer_sets
        return {'bearer_sets': bearers,
                'UE_sets': self._prepare_ue_sets_subsection_content(ues)
                }

    @staticmethod
    def _prepare_ue_sets_subsection_content(ues):
        if '1-1000' not in ues:
            return []
        ue = ues['1-1000']
        ue_sets_content = [{'ids': ue['ueid'],
                            'bearer': ue['bearer'],
                            'mcc': ue['mcc'],
                            'mnc': ue['mnc'],
                            'eia': ue['eia'],
                            'eea': ue['eea'],
                            }]
        return ue_sets_content
